// Native durability, paid auto-repair and distinct-target missile probe.
#define Generate_Mission_Starts Blast_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaignenemies.h"
#include <set>
#include <fstream>
static BuildingClass* ReadySam(const std::string& dir,bool own){Reset(dir);auto sam=new BuildingClass(STRUCT_SAM,own?HOUSE_GOOD:HOUSE_BAD);Check("place durability SAM",Put(sam,Center()));++ScenarioInit;sam->Begin_Mode(BSTATE_IDLE);--ScenarioInit;sam->Assign_Mission(MISSION_GUARD);sam->Commence();return sam;}
static void Durability(const std::string& dir){
 auto sam=ReadySam(dir,true);int base=sam->Class->MaxStrength;Check("new player SAM has fivefold max and current HP",Campaign_Max_Health(sam)==base*5&&sam->Strength==base*5&&sam->Health_Ratio()==0x100);
 sam->Status=3;int damage=200,before=sam->Strength;sam->Take_Damage(damage,0,WARHEAD_AP,nullptr);int ownLoss=before-sam->Strength;std::printf("PLAYER DAMAGE %d\n",ownLoss);
 auto enemy=ReadySam(dir,false);Check("enemy SAM keeps base maximum and current HP",Campaign_Max_Health(enemy)==base&&enemy->Strength==base);enemy->Status=3;damage=200;before=enemy->Strength;enemy->Take_Damage(damage,0,WARHEAD_AP,nullptr);int enemyLoss=before-enemy->Strength;Check("raised player SAM takes half stock damage",ownLoss*2==enemyLoss);
 auto underground=[&](bool own){auto s=ReadySam(dir,own);s->Status=0;int d=200,hp=s->Strength;s->Take_Damage(d,0,WARHEAD_AP,nullptr);return hp-s->Strength;};int buriedEnemy=underground(false),buriedOwn=underground(true);Check("buried SAM retains original protection plus new defense",buriedOwn==buriedEnemy/2);
 sam=ReadySam(dir,true);sam->Strength=base*5/2;PlayerPtr->Credits=50000;PlayerPtr->Tiberium=0;Campaign_Enemies_Mark_Extra(sam);int id=Buildings.ID(sam),hp=sam->Strength;
 Check("save damaged boosted SAM",Save_Game((dir+"/durable.sav").c_str(),"DURABLE SAM HALF HEALTH"));Check("reload damaged boosted SAM",Load_Game((dir+"/durable.sav").c_str()));sam=Buildings.Ptr(id);Check("reload preserves fivefold HP without multiplication",sam->Strength==hp&&Campaign_Max_Health(sam)==base*5&&sam->Health_Ratio()==0x80);Check("second reload still preserves HP",Load_Game((dir+"/durable.sav").c_str()));sam=Buildings.Ptr(id);Check("second reload is idempotent",sam->Strength==hp);
 // Remove only the new SAM footer to simulate a native legacy save. Its HP
 // comes from an explicitly ordinary pre-upgrade health value.
 sam->Strength=base/2;Check("write legacy-health fixture",Save_Game((dir+"/legacy.sav").c_str(),"OLD SAM HALF HEALTH"));
 {std::ifstream in(dir+"/legacy.sav",std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(in)),{});auto pos=bytes.rfind("CNCSAM03");Check("find new optional footer",pos!=std::string::npos);if(pos!=std::string::npos){bytes.resize(pos);std::ofstream out(dir+"/legacy.sav",std::ios::binary|std::ios::trunc);out.write(bytes.data(),bytes.size());}}
 Check("load pre-upgrade damaged SAM",Load_Game((dir+"/legacy.sav").c_str()));sam=Buildings.Ptr(id);Check("old save scales HP proportionally to fivefold cap",sam->Strength==base*5/2&&sam->Health_Ratio()==0x80);
 auto bad=HouseClass::As_Pointer(HOUSE_BAD);sam->House=bad;Campaign_SAM_Health_Apply(sam);Check("enemy ownership removes HP perk proportionally",sam->Strength==base/2&&Campaign_Max_Health(sam)==base);sam->House=PlayerPtr;Campaign_SAM_Health_Apply(sam);Check("returning local ownership restores proportional HP",sam->Strength==base*5/2);
}
static void Repair(const std::string& dir){auto sam=ReadySam(dir,true);int maximum=Campaign_Max_Health(sam);PlayerPtr->Credits=50000;PlayerPtr->Tiberium=0;sam->Strength=maximum-2;sam->IsRepairing=false;Frame=15;int money=PlayerPtr->Available_Money();sam->AI();Check("damaged SAM automatically repairs and caps at boosted maximum",sam->Strength==maximum&&!sam->IsRepairing);Check("automatic repair charges original repair cost",PlayerPtr->Available_Money()==money-sam->Class->Repair_Cost());money=PlayerPtr->Available_Money();Frame=30;sam->AI();Check("full-health SAM stops charging",PlayerPtr->Available_Money()==money);
 sam->Strength=maximum-20;PlayerPtr->Credits=0;PlayerPtr->Tiberium=0;Frame=45;int hp=sam->Strength;sam->AI();Check("empty wallet prevents free repair",sam->Strength==hp);PlayerPtr->Credits=50000;Frame=60;sam->AI();Check("repair resumes automatically when funds return",sam->Strength>hp);
 auto enemy=ReadySam(dir,false);enemy->Strength-=20;enemy->IsRepairing=false;hp=enemy->Strength;Frame=15;enemy->AI();Check("enemy SAM receives no new automatic repair",enemy->Strength==hp&&!enemy->IsRepairing);
}
static void Targets(const std::string& dir,int count){auto sam=ReadySam(dir,true);std::vector<UnitClass*> enemies;for(int i=0;i<count;++i){auto unit=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place separate missile target",Put(unit,XY_Cell(Cell_X(Coord_Cell(sam->Coord))+2,Cell_Y(Coord_Cell(sam->Coord))+2)));unit->IsDiscoveredByPlayer=true;unit->Strength=30000;enemies.push_back(unit);}auto primary=enemies[0];if(count==1){auto neutral=new BuildingClass(STRUCT_POWER,HOUSE_NEUTRAL);Check("place excluded neutral secondary building",Put(neutral,Coord_Cell(sam->Coord)));neutral->IsDiscoveredByPlayer=true;}auto shot=static_cast<TechnoClass*>(sam)->Fire_At(primary->As_Target(),0);Check("base missile exists",shot!=nullptr);int expected=1;Check("normal salvo has density-proportional distinct missiles",Bullets.Count()==expected);std::set<COORDINATE> aims;bool valid=true;for(int i=0;i<Bullets.Count();++i){auto missile=Bullets.Ptr(i);aims.insert(missile->Fuse_Target());bool known=false;for(auto enemy:enemies)if(missile->Fuse_Target()==enemy->Target_Coord())known=true;valid=valid&&known&&missile->Strength==50;}
 std::printf("DISTINCT enemies=%d missiles=%d aims=%zu\n",count,Bullets.Count(),aims.size());Check("base and every extra missile have different real target coordinates",aims.size()==size_t(expected)&&valid);
 for(int i=Bullets.Count()-1;i>=0;--i)delete Bullets.Ptr(i);
 if(count==1){static_cast<TechnoClass*>(sam)->Fire_At(primary->As_Target(),0);Check("single remaining enemy does not receive duplicate extra missiles",Bullets.Count()==1);}
}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Durability(dir);Repair(dir);for(int count:{1,2,5,10,20})Targets(dir,count);auto preview=ReadySam(dir,true);preview->Strength=Campaign_Max_Health(preview)-100;PlayerPtr->Credits=50000;PlayerPtr->Tiberium=0;for(int i=0;i<8;++i){auto target=new UnitClass(UNIT_MTANK,HOUSE_BAD);Put(target,XY_Cell(Cell_X(Coord_Cell(preview->Coord))+7,Cell_Y(Coord_Cell(preview->Coord))+i/2));target->IsDiscoveredByPlayer=true;target->Assign_Mission(MISSION_SLEEP);target->Commence();Campaign_Enemies_Mark_Extra(target);}for(int i=0;i<MAP_CELL_TOTAL;++i)if(Map.In_Radar(i))Map.Map_Cell(i,PlayerPtr,true);Map.Activate(1);preview->Select();++ScenarioInit;Map.Set_Tactical_Position(Cell_Coord(XY_Cell(MAX(Map.MapCellX,Cell_X(Coord_Cell(preview->Coord))-5),MAX(Map.MapCellY,Cell_Y(Coord_Cell(preview->Coord))-5))));--ScenarioInit;Check("save private durability display fixture",Save_Game((dir+"/savegame.092").c_str(),"DURABLE AUTO REPAIR SPREAD SAM"));std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
